import{_ as t,o as d,c as o,a0 as c}from"./chunks/framework.BDx3ik-m.js";const u=JSON.parse('{"title":"WB SDK ↔ OpenAPI Conformance — Master Audit","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/conformance-master-report.md","filePath":"api-reference/conformance-master-report.md"}'),r={name:"api-reference/conformance-master-report.md"};function a(i,e,s,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="wb-sdk-↔-openapi-conformance-—-master-audit" tabindex="-1">WB SDK ↔ OpenAPI Conformance — Master Audit <a class="header-anchor" href="#wb-sdk-↔-openapi-conformance-—-master-audit" aria-label="Permalink to &quot;WB SDK ↔ OpenAPI Conformance — Master Audit&quot;">​</a></h1><p>12 modules audited against the etalon (<code>docs/api-reference/raw-yaml/</code>, 9 live Jul-2026 + 3 local Feb-2026 stopgap). Verdicts from per-module deep-dive (automated matcher + manual classification + enum/schema checks).</p><h2 id="per-module-verdict" tabindex="-1">Per-module verdict <a class="header-anchor" href="#per-module-verdict" aria-label="Permalink to &quot;Per-module verdict&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Coverage</th><th>Verdict</th><th>Headline</th></tr></thead><tbody><tr><td>products</td><td>49/49</td><td>✅ PASS</td><td>matcher false-positives; all 3 enums match</td></tr><tr><td>communications</td><td>25/25</td><td>✅ PASS</td><td>matcher false-positives (no-operationId paths); 12 enums match</td></tr><tr><td>tariffs</td><td>5/5</td><td>✅ PASS</td><td>clean; 0 enums; schemas faithful</td></tr><tr><td>ordersFBW</td><td>7/7</td><td>✅ PASS</td><td>4 enums match; 3 benign additive optional fields</td></tr><tr><td>analytics</td><td>17/18</td><td>⚠️ GAPS</td><td>1 real gap (<code>/item-rating</code>); 1 enum widened</td></tr><tr><td>general</td><td>9/10</td><td>🔴 DEFECTS</td><td><code>AccessCode</code> enum drift; 3 JamSubscription enums → string</td></tr><tr><td>promotion</td><td>31/39</td><td>🔴 DEFECTS</td><td><code>BidType</code>, <code>CampaignPlacementType</code>; 8 gaps</td></tr><tr><td>ordersFBS</td><td>34/35</td><td>🔴 DEFECTS</td><td><code>DeleteMetaParams.key</code> enum erased; 1 gap; schema fields</td></tr><tr><td>ordersDBS</td><td>19/19 active</td><td>🔴 DEFECTS</td><td><code>deliveryType</code> missing <code>edbs</code>; status enum value drift; meta types</td></tr><tr><td><strong>inStorePickup</strong></td><td>4/18</td><td>🚨 DEFECTS</td><td><strong>PATH DRIFT — 12 methods on stale URLs</strong></td></tr><tr><td>reports</td><td>24/24</td><td>🔴 DEFECTS</td><td>double-wrapped response types (structural)</td></tr><tr><td>finances</td><td>12/12</td><td>🔴 DEFECTS</td><td><code>report_type</code> spurious <code>4</code>; <code>reportType</code> widened; missing B2B TIN</td></tr></tbody></table><p>Adjusted real coverage ≈ <strong>235/273</strong> (products/communications false-positives removed; ordersDBS 12 &quot;missing&quot; are deprecated).</p><hr><h2 id="🚨-critical-—-instorepickup-path-drift-potentially-broken-at-runtime" tabindex="-1">🚨 CRITICAL — inStorePickup path drift (potentially broken at runtime) <a class="header-anchor" href="#🚨-critical-—-instorepickup-path-drift-potentially-broken-at-runtime" aria-label="Permalink to &quot;🚨 CRITICAL — inStorePickup path drift (potentially broken at runtime)&quot;">​</a></h2><p>12 methods call <strong>stale <code>/api/v3/click-collect/orders/{id}/...</code></strong> (single-order, PATCH/PUT/DELETE) while the spec serves them at <strong><code>/api/marketplace/v3/click-collect/...</code></strong> (batch, POST). WB migrated these → SDK URLs may 404 or hit old endpoints.</p><table tabindex="0"><thead><tr><th>Spec (current)</th><th>SDK (stale)</th></tr></thead><tbody><tr><td><code>POST /api/marketplace/v3/click-collect/orders/status/confirm</code></td><td><code>PATCH /api/v3/click-collect/orders/{id}/confirm</code></td></tr><tr><td><code>.../status/prepare</code> <code>.../receive</code> <code>.../reject</code> <code>.../cancel</code></td><td>(same pattern, PATCH single-order)</td></tr><tr><td><code>POST .../status/info</code></td><td><code>POST /api/v3/click-collect/orders/status</code></td></tr><tr><td><code>POST .../meta/details</code> <code>.../delete</code> <code>.../sgtin</code> <code>.../uin</code> <code>.../imei</code> <code>.../gtin</code></td><td>GET/DELETE/PUT on <code>/api/v3/.../{id}/meta/...</code></td></tr></tbody></table><ul><li>1 real gap (<code>customs-declaration</code>), 1 spec-deprecated (<code>meta/info</code>). Type defects: <code>wbStatus</code> missing <code>sorted</code> (types:218), <code>deleteOrdersMeta.key</code> string-not-enum, <code>orderId</code>→<code>id</code> rename drift, missing <code>options.isB2b</code>.</li></ul><hr><h2 id="type-defects-prioritized-with-file-line" tabindex="-1">Type defects (prioritized, with file:line) <a class="header-anchor" href="#type-defects-prioritized-with-file-line" aria-label="Permalink to &quot;Type defects (prioritized, with file:line)&quot;">​</a></h2><p><strong>promotion</strong> (<code>src/types/promotion.types.ts</code>)</p><ul><li><code>BidType = &#39;auto&#39; | &#39;manual&#39;</code> (:1513) — spec <code>[manual, unified]</code>. <strong>Wrong values.</strong></li><li><code>CampaignPlacementType = &#39;search&#39; | &#39;recommendations&#39;</code> (:1518) — spec <code>[combined, search, recommendation]</code>. <strong>Missing <code>combined</code>; plural-vs-singular.</strong></li></ul><p><strong>general</strong> (<code>src/types/general.types.ts</code>)</p><ul><li><code>AccessCode</code> (:83) — missing <code>brandzone</code>, <code>brandzoneSubscribe</code>, <code>marketplace</code>, <code>oldAnalyticsReports</code>; extra <code>feedbacksQuestions</code>, <code>wbPoint</code>.</li><li><code>JamSubscriptionDetails.state/activationSource/level</code> (:301/303/305) — widened to <code>string</code> (spec enums: <code>[active,inactive]</code>, <code>[constructor,jam]</code>, <code>[standard,advanced,premium]</code>).</li></ul><p><strong>ordersFBS</strong> (<code>src/types/orders-fbs.types.ts</code>)</p><ul><li><code>DeleteMetaParams.key?: string</code> (:94) — spec closed enum <code>[imei,uin,gtin,sgtin,customsDeclaration]</code>.</li><li><code>OrderNew</code>/<code>Supply</code> missing <code>isPickupPointShipmentAllowed</code>; <code>Supply</code> missing <code>recommendedWhId</code>.</li></ul><p><strong>ordersDBS</strong> (<code>src/types/orders-dbs.types.ts</code>)</p><ul><li><code>DBSOrderNew.deliveryType?: &#39;dbs&#39;</code> (:47) — spec <code>[dbs, edbs]</code>. <strong>Missing <code>edbs</code>.</strong></li><li><code>DBSSupplierStatus</code> (:154) uses <code>canceled_by_missed_call</code> — spec <code>cancel_missed_call</code>.</li><li><code>DBSWbStatus</code> (:166) has spurious <code>sorted</code> (not in DBS spec).</li><li><code>DBSOrderMeta</code> imei/uin/gtin typed <code>{value?: number}</code> — spec strings.</li><li>Schema drift: missing <code>options/groupId/finalPrice/convertedFinalPrice/replacementPhone</code>; misplaced <code>ddate/dTime*</code>.</li></ul><p><strong>reports</strong> (<code>src/types/reports.types.ts</code>)</p><ul><li><code>MeasurementPenaltiesResponse</code>/<code>WarehouseMeasurementsV2Response</code> (:905-922) — <strong>double-wrapped</strong> (structural mismatch vs spec).</li><li><code>IncomesItem</code> (:10) — orphan type, no spec backing.</li></ul><p><strong>finances</strong> (<code>src/types/finances.types.ts</code>)</p><ul><li><code>DetailReportItem.report_type?: 1|2|3|4</code> (:238) — spec <code>[1,2,3]</code>. <strong>Spurious <code>4</code>.</strong></li><li><code>SalesReportListRes.reportType</code> (:402), <code>SalesReportsDetailedRes.reportType</code> (:455) — widened to <code>number</code> (should be <code>[1,2,3]</code>).</li><li>Missing <code>b2bCustomerTin</code> / <code>b2b_customer_tin</code> (B2B buyer TIN).</li></ul><p><strong>analytics</strong> (<code>src/types/analytics.types.ts</code>)</p><ul><li><code>SalesFunnelGroupReq.params.aggregationLevel?: string</code> (:684) — should be <code>[day,week,month]</code>.</li></ul><hr><h2 id="real-endpoint-gaps-features-to-add" tabindex="-1">Real endpoint gaps (features to add) <a class="header-anchor" href="#real-endpoint-gaps-features-to-add" aria-label="Permalink to &quot;Real endpoint gaps (features to add)&quot;">​</a></h2><ul><li><strong>promotion (8):</strong> <code>/adv/v1/upd</code>, <code>/adv/v1/payments</code> (finance history), <code>/api/advert/v1/config</code>, v1 normquery bids/stats (seller currency), <code>/adv/v0/normquery/list</code>, media-campaigns API (<code>advert-media-api</code> — new domain: <code>/adv/v1/adverts</code>, <code>/adv/v1/advert</code>).</li><li><strong>ordersFBS (1):</strong> <code>GET /api/marketplace/v3/fbs/orders/archive</code>.</li><li><strong>general (1):</strong> <code>GET /api/common/v1/tariff-constructor/options</code> (Plan Builder).</li><li><strong>analytics (1):</strong> <code>POST /api/analytics/v1/item-rating</code>.</li><li><strong>inStorePickup (1):</strong> <code>POST .../meta/customs-declaration</code> (B2B).</li></ul><h2 id="cleanup-deprecated-sdk-only" tabindex="-1">Cleanup (deprecated SDK-only) <a class="header-anchor" href="#cleanup-deprecated-sdk-only" aria-label="Permalink to &quot;Cleanup (deprecated SDK-only)&quot;">​</a></h2><ul><li>promotion: 6 deprecated v0 methods (<code>/adv/v0/auction/bids</code>, <code>/adv/v0/auction/adverts</code>, <code>/adv/v1/auto/*</code>, <code>/adv/v0/stats/keywords</code>, <code>/adv/v1/promotion/adverts</code>).</li></ul><h2 id="matcher-limitations-for-tooling-v2" tabindex="-1">Matcher limitations (for tooling v2) <a class="header-anchor" href="#matcher-limitations-for-tooling-v2" aria-label="Permalink to &quot;Matcher limitations (for tooling v2)&quot;">​</a></h2><ul><li>products/communications false-positives: spec paths lacking <code>operationId</code> + dual GET/PATCH on same path weren&#39;t matched. Improve matcher to key on <code>(server, method, path)</code> and allow multi-method paths.</li></ul>',33)])])}const h=t(r,[["render",a]]);export{u as __pageData,h as default};
